const mem = $getWorkflowStaticData('global');
const first = !mem.seen; mem.seen = mem.seen || [];
const out = [];
for (const i of $input.all()) {                           // one item per certificate
  const c = i.json;
  if (!c.id || mem.seen.includes(c.id)) continue;
  mem.seen.push(c.id);
  if (!first) out.push(`${(c.dns_names || []).join(', ')} | ${c.issuer?.friendly_name || c.issuer?.name || 'unknown issuer'} | ${(c.not_before || '').slice(0, 10)}`);
}
mem.seen = mem.seen.slice(-1000);
if (!out.length) return [];                               // first run only learns
return [{ json: { title: `${out.length} new certificate(s) for your domains`,
  message: out.join('\n') + '\n\nExpected? Fine. Unknown name or issuer? Check it now.', tags: ['mag'] } }];
